var initToc=((a,b)=>{let c=`expanded`;a.classList.toggle(c,!1);b.classList.toggle(c,!1);b.style.display=`block`;b.style.maxHeight=`0`;b.style.overflow=`hidden`;b.style.transition=`max-height 0.3s ease-out`});document.addEventListener(`DOMContentLoaded`,()=>{let c=`expanded`;const a=document.querySelector(`.toc-title`);const b=document.querySelector(`.toc-list`);if(a&&b){initToc(a,b);const d=()=>{a.classList.toggle(c);b.classList.toggle(c);const d=b.classList.contains(c);b.style.maxHeight=d?`${b.scrollHeight}px`:`0`};a.addEventListener(`click`,d)}})